case "Text": return state === "sizes"
        ? (["body", "reading", "meta", "caption"] as const).map(size => <Text key={size} size={size}>{c.body}</Text>)
        : <Text tone={state === "strong" ? "strong" : undefined} variant={state === "numeral" || state === "caps" ? state : undefined}>{state === "numeral" ? <>128<small>{c.seat}</small></> : state === "caps" ? c.status : c.body}</Text>;

example.usage:
import { Text, tcrnComponentCss } from "@tcrn/ui-react/approved";
import { tcrnTokenCss } from "@tcrn/ui-tokens";
import "@tcrn/ui-tokens/fonts.css";

export function Example() {
  return <>
    <style>{tcrnTokenCss + "\n" + tcrnComponentCss}</style>
    <div data-tcrn-root data-tcrn-theme="light" style={{ display: "grid", gap: "var(--tcrn-space-2)" }}>
      <Text size="meta" tone="strong">Details</Text>
    </div>
  </>;
}
